60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    /**
76	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
77	     * and a domain containing at least one dot, with no whitespace in any segment.
78	     */
79	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
80	
81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        validateRequiredFields(ownerFieldsDto);
120	        HttpHeaders headers = new HttpHeaders();
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
123	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
124	            joinHousehold(owner);
125	        } else {
126	            requireUniqueHousehold(owner.getLastName(), owner.getAddress());
127	        }
128	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
129	        requireUniqueTelephone(telephone);
130	        owner.setTelephone(telephone);
131	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
132	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
133	        this.clinicService.saveOwner(owner);
134	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
135	        headers.setLocation(UriComponentsBuilder.newInstance()
136	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
137	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
138	    }
139	
140	    /**
141	     * Generates the customer code for a newly created owner, formatted {@code '<LAST3>-<NNNN>'}.
142	     * {@code LAST3} is the upper-cased first three letters of the last name and {@code NNNN} is a
143	     * global, 4-digit zero-padded sequence equal to one more than the current number of owners
144	     * (e.g. {@code 'SMI-0007'}).
145	     *
146	     * @param lastName the owner's last name
147	     * @return the generated customer code
148	     */
149	    private String generateCustomerCode(String lastName) {
150	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
151	        int sequence = this.clinicService.findAllOwners().size() + 1;
152	        return String.format("%s-%04d", last3, sequence);
153	    }
154	
155	    /**
156	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
157	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
158	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
159	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
160	     *
161	     * @param ownerFieldsDto the submitted owner fields
162	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
163	     */
164	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
165	        List<String> invalidFields = new ArrayList<>();
166	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
167	            invalidFields.add("firstName");
168	        }
169	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
170	            invalidFields.add("lastName");
171	        }
172	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
173	            invalidFields.add("address");
174	        }
175	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
176	            invalidFields.add("city");
177	        }
178	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
179	            invalidFields.add("telephone");
180	        }
181	        if (!invalidFields.isEmpty()) {
182	            throw new InvalidOwnerFieldsException(invalidFields);
183	        }
184	    }
185	
186	    /**
187	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
188	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
189	     * what gets stored and returned.
190	     *
191	     * @param telephone the raw telephone value from the request
192	     * @return the normalized E.164 telephone number
193	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
194	     */
195	    private String normalizeTelephone(String telephone) {
196	        String e164 = toE164(telephone);
197	        if (e164 == null) {
198	            throw new InvalidOwnerFieldsException(List.of("telephone"));
199	        }
200	        return e164;
201	    }
202	
203	    /**
204	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
205	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
206	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
207	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
208	     * it contains 8 to 15 digits after the {@code '+'}.
209	     *
210	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
211	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
212	     *
213	     * @param telephone the raw telephone value, possibly {@code null}
214	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
215	     */
216	    private String toE164(String telephone) {
217	        if (telephone == null) {
218	            return null;
219	        }
220	        String cleaned = telephone.replaceAll("[ \\-()]", "");
221	        String digits;
222	        if (cleaned.startsWith("+")) {
223	            digits = cleaned.substring(1);
224	        } else {
225	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
226	            digits = "61" + national;
227	        }
228	        if (!digits.matches("[0-9]{8,15}")) {
229	            return null;
230	        }
231	        return "+" + digits;
232	    }
233	
234	    /**
235	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
236	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
237	     * and returned lower-cased.
238	     *
239	     * @param email the raw email value from the request, possibly {@code null}
240	     * @return the lower-cased email, or {@code null} when none was supplied
241	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
242	     */
243	    private String normalizeEmail(String email) {
244	        if (!StringUtils.hasText(email)) {
245	            return null;
246	        }
247	        String trimmed = email.trim();
248	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
249	            throw new InvalidOwnerFieldsException(List.of("email"));
250	        }
251	        return trimmed.toLowerCase(Locale.ROOT);
252	    }
253	
254	    /**
255	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
256	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
257	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
258	     *
259	     * @param telephone the normalized (E.164) telephone of the owner being created
260	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
261	     */
262	    private void requireUniqueTelephone(String telephone) {
263	        boolean inUse = this.clinicService.findAllOwners().stream()
264	            .map(Owner::getTelephone)
265	            .filter(existing -> existing != null)
266	            .map(existing -> {
267	                String e164 = toE164(existing);
268	                return e164 != null ? e164 : existing;
269	            })
270	            .anyMatch(telephone::equals);
271	        if (inUse) {
272	            throw new DuplicateTelephoneException(telephone);
273	        }
274	    }
275	
276	    /**
277	     * Rejects an owner whose last name and address match those of an existing owner, where both are
278	     * compared case-insensitively and with runs of whitespace collapsed to a single space (a shared
279	     * household). The caller skips this check when the request opts in via {@code sharesHousehold}.
280	     *
281	     * @param lastName the last name of the owner being created
282	     * @param address the address of the owner being created
283	     * @throws DuplicateHouseholdException if another owner shares the same last name and address
284	     */
285	    private void requireUniqueHousehold(String lastName, String address) {
286	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
287	            throw new DuplicateHouseholdException(lastName, address);
288	        }
289	    }
290	
291	    /**
292	     * Returns the existing owners that belong to the same household as the given last name and
293	     * address, i.e. those whose last name and address match case-insensitively and with runs of
294	     * whitespace collapsed to a single space.
295	     *
296	     * @param lastName the last name to match
297	     * @param address the address to match
298	     * @return the matching owners (possibly empty, never {@code null})
299	     */
300	    private List<Owner> findHouseholdMembers(String lastName, String address) {
301	        String normalizedLastName = normalizeForHousehold(lastName);
302	        String normalizedAddress = normalizeAddress(address);
303	        return this.clinicService.findAllOwners().stream()
304	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
305	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
306	            .toList();
307	    }
308	
309	    /**
310	     * Joins the owner being created to the shared household of any existing owner(s) that have the
311	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
312	     * member of the household - the existing owners and the new one - is assigned the same stable
313	     * {@code householdId}, so the shared identifier can be read back from any of them.
314	     *
315	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
316	     * the owner is left without a {@code householdId}.
317	     *
318	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
319	     */
320	    private void joinHousehold(Owner owner) {
321	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
322	        if (members.isEmpty()) {
323	            return;
324	        }
325	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
326	        owner.setHouseholdId(householdId);
327	        for (Owner member : members) {
328	            if (!householdId.equals(member.getHouseholdId())) {
329	                member.setHouseholdId(householdId);
330	                this.clinicService.saveOwner(member);
331	            }
332	        }
333	    }
334	
335	    /**
336	     * Computes the stable, shared household identifier for a last name and address. The value is
337	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
338	     * name and address, so every owner in the same household computes the same identifier.
339	     *
340	     * @param lastName the last name of the household
341	     * @param address the address of the household
342	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
343	     */
344	    private String computeHouseholdId(String lastName, String address) {
345	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
346	        try {
347	            byte[] digest = MessageDigest.getInstance("SHA-256")
348	                .digest(key.getBytes(StandardCharsets.UTF_8));
349	            StringBuilder hex = new StringBuilder();
350	            for (int i = 0; i < 6; i++) {
351	                hex.append(String.format("%02X", digest[i]));
352	            }
353	            return "HH-" + hex;
354	        } catch (NoSuchAlgorithmException e) {
355	            throw new IllegalStateException("SHA-256 algorithm not available", e);
356	        }
357	    }
358	
359	    /**
360	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
361	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
362	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
363	     *
364	     * @param value the raw value, possibly {@code null}
365	     * @return the normalized value
366	     */
367	    private String normalizeForHousehold(String value) {
368	        if (value == null) {
369	            return "";
370	        }
371	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
372	    }
373	
374	    /**
375	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
376	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
377	     */
378	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
379	        "ST", "STREET",
380	        "RD", "ROAD",
381	        "AVE", "AVENUE");
382	
383	    /**
384	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
385	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
386	     * is upper-cased, and common street-type abbreviations are expanded as whole words
387	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
388	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
389	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
390	     *
391	     * @param address the raw address value, possibly {@code null}
392	     * @return the normalized address
393	     */
394	    private String normalizeAddress(String address) {
395	        if (address == null) {
396	            return "";
397	        }
398	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
399	        if (collapsed.isEmpty()) {
400	            return "";
401	        }
402	        String[] tokens = collapsed.split(" ");
403	        StringBuilder normalized = new StringBuilder();
404	        for (int i = 0; i < tokens.length; i++) {
405	            if (i > 0) {
406	                normalized.append(' ');
407	            }
408	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
409	        }
410	        return normalized.toString();
411	    }
412	
413	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
414	    @Override
415	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
416	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
417	        if (currentOwner == null) {
418	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
419	        }
420	        currentOwner.setAddress(ownerFieldsDto.getAddress());
421	        currentOwner.setCity(ownerFieldsDto.getCity());
422	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
423	        currentOwner.setLastName(ownerFieldsDto.getLastName());
424	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
425	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
426	        this.clinicService.saveOwner(currentOwner);
427	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
428	    }
429	
430	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
431	    @Transactional
432	    @Override
433	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
434	        Owner owner = this.clinicService.findOwnerById(ownerId);
435	        if (owner == null) {
436	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
437	        }
438	        this.clinicService.deleteOwner(owner);
439	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
440	    }
441	
442	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
443	    @Override
444	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
445	        Owner owner = this.clinicService.findOwnerById(ownerId);
446	        if (owner == null) {
447	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
448	        }
449	        HttpHeaders headers = new HttpHeaders();
450	        Pet pet = petMapper.toPet(petFieldsDto);
451	        owner.setId(ownerId);
452	        pet.setOwner(owner);
453	        pet.getType().setName(null);
454	        this.clinicService.savePet(pet);
455	        PetDto petDto = petMapper.toPetDto(pet);
456	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
457	            .buildAndExpand(pet.getId()).toUri());
458	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
459	    }
460	
461	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
462	    @Override
463	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
464	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
465	        if (currentOwner != null) {
466	            Pet currentPet = this.clinicService.findPetById(petId);
467	            if (currentPet != null) {
468	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
469	                currentPet.setName(petFieldsDto.getName());
470	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
471	                this.clinicService.savePet(currentPet);
472	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
473	            }
474	        }
475	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
476	    }
477	
478	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
479	    @Override
480	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
481	        HttpHeaders headers = new HttpHeaders();
482	        Visit visit = visitMapper.toVisit(visitFieldsDto);
483	        Pet pet = new Pet();
484	        pet.setId(petId);
485	        visit.setPet(pet);
486	        this.clinicService.saveVisit(visit);
487	        VisitDto visitDto = visitMapper.toVisitDto(visit);
488	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
489	            .buildAndExpand(visit.getId()).toUri());
490	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
491	    }
492	
493	
494	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
495	    @Override
496	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
497	        Owner owner = this.clinicService.findOwnerById(ownerId);
498	        if (owner != null) {
499	            Pet pet = owner.getPet(petId);
500	            if (pet != null) {
501	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
502	            }
503	        }
504	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
505	    }
